{\it Notation:} The set of real numbers and the set of integers are denoted by $\mathbb{R}$ and $\mathbb{I}$, respectively. We define $\mathbb{I}_{A}:=\mathbb{I}\cap A$, where $A$ is a set; $\mathbb{I}_{>0}:=\mathbb{I}\cap(0,\infty)$; $\mathbb{I}_{\geq 0}:=\mathbb{I}\cap[0,\infty)$; $\mathbb{R}_{>0}:=(0,\infty)$; and $\mathbb{R}_{\geq 0}:=[0,\infty)$. For $A\subseteq X$, $f:X\rightarrow Y$, and $x\in X$, where $X$ and $Y$ are linear spaces, $A+x := \{x'+x:x'\in A\}$ and $f(X):=\{f(x)\in Y:x\in X\}$. Vectors are treated as column vectors. We use the syntax: $[M_1;\cdots;M_n]:=[M_1^\top\,\cdots\,M_n^\top]^\top$; $\{M_i\}_{i\in U}:=[M_{i_1}; \cdots; M_{i_{m}}]$; $\{M_{i,j}\}_{i\in U,j\in V}:=\{\{M_{i,j}^\top\}_{j\in V}^\top\}_{i\in U}$, where, $U=\{i_1<\cdots<i_{m}\}$ and $V=\{j_1<\cdots<j_{n}\}$ are strictly ordered sets. Furthermore, $v[i]$ is the $i$-th component of vector $v$; $M[i,j]$ is the $(i,j)$-th component of matrix $M$; $v[I]:=\{v[i]\}_{i\in I}$; $M[I,J]:=\{M[i,j]\}_{i\in I,j\in J}$. For a function $\phi:\mathbb{R}^{n}\rightarrow \mathbb{R}$ and variable vectors $y\in\mathbb{R}^{p}$, $z\in\mathbb{R}^{q}$, $\nabla^2_{yz}\phi(x):=\{\frac{\partial^2}{\partial y[i]\partial z[j]}\phi(x)\}_{i\in\mathbb{I}_{[1,p]},j\in\mathbb{I}_{[1,q]}}$. For a vector function $\varphi:\mathbb{R}^{n}\rightarrow \mathbb{R}^m$ and a variable vector $w\in\mathbb{R}^{s}$, $\nabla_{w}\varphi(x):=\{\frac{\partial}{\partial w[j]}\varphi(x)[i]\}_{i\in\mathbb{I}_{[1,m]},j\in\mathbb{I}_{[1,s]}}$. We use the shorthand notation $\nabla^2\phi(x):=\nabla^2_{xx}\phi(x)$, $\nabla\varphi(x):=\nabla_x\varphi(x)$. Vector 2-norms and induced 2-norms of matrices are denoted by $\Vert\cdot\Vert$. For matrices $A$ and $B$, $A\succ(\succeq) B$ indicates that $A-B$ is positive (semi)-definite while $A>(\geq) B$ denotes a componentwise inequality. The identity matrix is denoted as $\bI$ and the zero matrix or vector are denoted as $\bzero$. Specific notations will be introduced at the first appearance. {\blue We denote the largest and smallest eigenvalues of a symmetric matrix and non-trivial singular values of general matrices by $\olambda(\cdot)$, $\ulambda(\cdot)$, $\osigma(\cdot)$, and $\usigma(\cdot)$}.

{\it Settings:} We study gsNLPs of the following form: 
\begin{subequations}\label{eqn:prob}
  \begin{align}
    \min_{\{x_i\in\mathbb{R}^{r_i}\}_{i\in \cV}}\;& \sum_{i\in \cV}f_i(\{x_j\}_{j\in \cN_\cG[i]};\{p_j\}_{j\in \cN_\cG[i]})\label{eqn:prob-obj}\\
    \st\;& c^E_i(\{x_j\}_{j\in \cN_\cG[i]};\{p_j\}_{j\in \cN_\cG[i]}) = 0,\;i\in \cV,\;(y^E_i)\label{eqn:prob-eq}\\
                                                  &c^I_i(\{x_j\}_{j\in \cN_\cG[i]};\{p_j\}_{j\in \cN_\cG[i]}) \geq 0,\;i\in \cV,\;(y^I_i)\label{eqn:prob-ineq},
  \end{align}
\end{subequations}
where $\cG=(\cV,\cE)$ is an undirected graph, $\cV$ is a strictly ordered node set, $\cE\subseteq \{\{i,j\}\subseteq \cV: i\neq j\}$ is the edge set, and $\cN_\cG[i]:=\{j\in \cV:\{i,j\}\in \cE\}\cup\{i\}$ denotes the closed neighborhood\footnote{Note that closed neighborhood is different from the standard notion of neighborhood (also called open neighborhood), defined as $\cN_\cG(i):=\{j\in \cV:\{i,j\}\in \cE\}$. The closed neighborhood of a node contains itself whereas the open neighborhood does not.} of $i\in \cV$. For each node $i\in \cV$, $x_i\in\mathbb{R}^{r_i}$ is the primal variable; $p_i\in\mathbb{R}^{l_i}$ is the data; $f_i:\prod_{j\in \cN_\cG[i]}\mathbb{R}^{r_j}\times\prod_{j\in \cN_\cG[i]}\mathbb{R}^{l_j}\rightarrow \mathbb{R}$ is the objective function; $c^E_i:\prod_{j\in \cN_\cG[i]}\mathbb{R}^{r_j}\times \prod_{j\in \cN_\cG[i]}\mathbb{R}^{l_j}\rightarrow \mathbb{R}^{m^E_i}$ is the equality constraint function; $c^I_i:\prod_{j\in \cN_\cG[i]}\mathbb{R}^{r_j}\times \prod_{j\in \cN_\cG[i]}\mathbb{R}^{l_j}\rightarrow \mathbb{R}^{m^I_i}$ is the inequality constraint function; and $y^E_i\in\mathbb{R}^{m^E_i}$ and $y^I_i\in\mathbb{R}^{m^I_i}$ are the dual variables associated with \eqref{eqn:prob-eq} and \eqref{eqn:prob-ineq}. The objective and constraint functions of node $i$ depend on the variables $\{x_j\}_{j\in \cN_\cG[i]}$ and data $\{p_j\}_{j\in \cN_\cG[i]}$ of the neighboring nodes. That is, node $i$ is coupled algebraically only to its neighbors, and the topology of such connectivity is dictated by $\cG$.

{\blue
  We can express \eqref{eqn:prob} as a standard NLP of the following form:
 \begin{subequations}
   \begin{align}
     P(\bp):\;\min_{\bx}\;&\bff(\bx;\bp)\\
     \st\;&\bc^E(\bx;\bp)=\bzero,\; (\by^E)\\
                          &\bc^I(\bx;\bp)\geq \bzero,\;\;(\by^I).
   \end{align}
 \end{subequations}
 Here, we compact the notation as: $\bx:=\{x_i\}_{i\in \cV}$; $\by^E:=\{y^E_i\}_{i\in \cV}$; $\by^I:=\{y^I_i\}_{i\in \cV}$; $\bp:=\{p_i\}_{i\in \cV}$; $\br=\sum_{i\in \cV} r_i$; $\bm^E=\sum_{i\in \cV} m^E_i$; $\bm^I=\sum_{i\in \cV} m^I_i$; $\bl = \sum_{i\in \cV}l_i$; $\bff(\bx;\bp):=\sum_{i\in \cV}f_i(\{x_j\}_{j\in \cN_\cG[i]};\{p_j\}_{j\in \cN_\cG[i]})$; $\bc^E(\bx;\bp):=\{c^E_i(\{x_j\}_{j\in \cN_\cG[i]};\{p_j\}_{j\in \cN_\cG[i]})\}_{i\in \cV}$; and $\bc^I(\bx;\bp):=\{c^I_i(\{x_j\}_{j\in \cN_\cG[i]};\{p_j\}_{j\in \cN_\cG[i]})\}_{i\in \cV}$. We also define $c_i(\cdot):=[c^E_i(\cdot);c^I_i(\cdot)]$; $y_i:=[y^E_i;y^I_i]$; $z_i:=[x_i;y_i]$; $m_i=m^E_i+m^I_i$; $n_i=r_i+m_i$; $\by:=\{y_i\}_{i\in \cV}$; $\bz:=\{z_i\}_{i\in \cV}$;  $\bm=\sum_{i\in \cV} m_i$; $\bn=\sum_{i\in \cV} n_i$; and $\bc(\bx;\bp):=\{c_i(\{x_j\}_{j\in \cN_\cG[i]};\{p_j\}_{j\in \cN_\cG[i]})\}_{i\in \cV}$.
}


\begin{definition}[Graph Distance and Diameter]\label{def:distance}
  The distance $d_\cG(i,j)$ between nodes $i,j\in \cV$ on graph $\cG=(\cV,\cE)$ is the number of edges in the shortest path connecting them; {if a shortest path does not exist, the distance is $+\infty$}. Furthermore, the diameter $D_\cG$ of $\cG$ is the longest distance between any pair of nodes in $\cV$.
\end{definition}
\begin{proposition}\label{prop:metric}
  The distance $d_\cG:\cV\times \cV \rightarrow \mathbb{I}_{\geq 0}{\cup\{\infty\}}$ is a metric on $\cV$; that is, (a) $d_\cG(i,j)\geq 0$ for any $i,j\in \cV$; (b) $i=j$ if and only if $d_\cG(i,j)=0$; (c) $d_\cG(i,j)=d_\cG(j,i)$ for any $i,j\in \cV$; (d) $d_\cG(i,j)\leq d_\cG(i,k)+d_\cG(k,j)$ for any $i,j,k\in \cV$.
\end{proposition}
The proof of this result is straightforward and thus omitted. {Note that the shortest path does not exist when the graph is not connected. } 

{A graph-structured matrix $X\in\mathbb{R}^{m\times n}$ is indexed by a graph $\cG=(\cV,\cE)$ and a pair of index set families $\cI:=\{I_{i}\}_{i\in \cV}$ and $\cJ:=\{J_{i}\}_{i\in \cV}$ that partition\footnote{In this paper, we call a family $\{X_1,\cdots,X_k\}$ of subsets of $X$ to be a partition if $\bigcup_{k=1}^K X_k=X$ and $X_1,\cdots,X_k$ are disjoint; here, {\it we allow $X_k$ to be empty sets}. Note that this differs from the standard definition of a partition, where the nonemptiness of $X_k$ is enforced. This modification allows us to handle nodes with empty variables, constraints, or data, which is useful in many settings.} $\mathbb{I}_{[1,m]}$ and $\mathbb{I}_{[1,n]}$, respectively. We refer to $X_{[i][j]}$ as the $[i][j]$-block of matrix $X$, which can later be associated with the node pair $(i,j)$. It should be noted that the short-hand notation $X_{[i][j]}:=X[I_i,J_j]$ assumes that the proper graph and index set families $(\cG,\cI,\cJ)$ are introduced or can be inferred from the context. We are now ready to introduce the concept of graph-induced {\it bandwidth}.} 

\begin{definition}[Graph-Induced Bandwidth]\label{def:bandwidth}
  Consider a matrix $X\in\mathbb{R}^{m\times n}$, a graph $\cG=(\cV,\cE)$, and index sets $\cI=\{I_i\}_{i\in \cV}$, $\cJ=\{J_i\}_{i\in \cV}$ that partition $\mathbb{I}_{[1,m]}$ and $\mathbb{I}_{[1,n]}$, respectively. Matrix $X$ is said to have bandwidth $B$ induced by $(\cG,\cI,\cJ)$, if $B$ is the smallest nonnegative integer such that $X_{[i][j]}=\bzero$ for any $i,j\in \cV$ with $d_\cG(i,j)> B$, where $X_{[i][j]}:=X[I_i,J_j]$.
\end{definition}


We use $\bz^\star \in\mathbb{R}^{\bn}$ to denote the primal-dual solution of $P(\bp^\star)$. We refer to $\bp^\star$ as the base data and $\bz^\star$ as the base solution. We denote the primal and dual components of $\bz^\star=\{z^\star_i\}_{i\in\cV}=\{[x^\star_i;y^\star_i]\}_{i\in\cV}$ as $\bx^\star:=\{x^\star_i\}_{i\in\cV}$ and $\by^\star=\{y^\star_i\}_{i\in\cV}$, respectively. We say that $\bz^\star$ is a primal-dual solution if $\bx^\star$ satisfies the first-order optimality conditions with Lagrange multiplier $\by^\star$ (see \cite{nocedal2006numerical}). We now make key assumptions that are necessary to establish our main results. 

\begin{assumption}[Twice Continuous Differentiability of Functions]\label{ass:c2}
  The functions $\bff:\mathbb{R}^{\br}\times \mathbb{R}^{\bl}\rightarrow \mathbb{R}$ and $\bc:\mathbb{R}^{\br}\times \mathbb{R}^{\bl}\rightarrow \mathbb{R}^{\bm}$ are twice continuously differentiable in the neighborhood of $[\bx^\star;\bp^\star]$.
\end{assumption}

\begin{assumption}[Regularity of Solution]\label{ass:regularity}
  The base solution $\bz^\star$ satisfies SSOSC and LICQ for $P(\bp^\star)$ with base data $\bp^\star$.
\end{assumption}
We recall that SSOSC requires positive definiteness of the reduced Hessian of the Lagrangian at $\bz^\star$. The reduced Hessian is the Hessian projected on the null space defined by equality constraints and active inequality constraints with nonzero duals. LICQ requires that the constraint Jacobian defined by equality and active inequality constraints are linearly independent at $\bz^\star$. These requirements are stated as: 
\begin{align*}
  ReH(\nabla^2_{\bx\bx}\cL(\bz^\star;\bp^\star),\nabla_{\bx}\bc(\bx^\star;\bp^\star)[\cA^0(\bp^\star),:]) &\succ \bzero\tag{SSOSC}\\
  \usigma(\nabla_{\bx}\bc(\bx^\star;\bp^\star)[\cA^1(\bp^\star),:]) &> 0 \tag{LICQ}.
\end{align*}
Here, $\cL(\bz;\bp) := \bff(\bx;\bp)-\by^\top \bc(\bx;\bp)$ is the Lagrange function, $ReH(H,A):=Z^\top HZ$ is the reduced Hessian, where $Z$ is a null-space matrix of $A$, and
\begin{align}\label{eqn:active-set-defs}
  \cA^0(\bp^\star)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\star)[i]=0,\;\by^\star[i]\neq 0\}\\
  \cA^1(\bp^\star)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\star)[i]=0\},
\end{align}
where $\cA^E$ and $\cA^I$ are the set of equality and inequality constraint indices. Hereafter, we call a solution of gsNLP regular if the solution satisfies SSOSC and LICQ. Note that SSOSC and LICQ are standard assumptions used in NLP sensitivity theory \cite{robinson1980strongly}. We now state the classical sensitivity result.


Under Lemma \ref{lem:nlp-sensitivity}, the rate of change $D_{\bq}\bz^\dag(\bp)$ of the primal-dual solution of $P(\bp)$ (for a given direction $\bq$) can be quantified by using the solution of $QP(\bp,\bq)$. For given $\bp$ and $\bq$, the parameters in $QP(\bp,\bq)$ can be evaluated explicitly and thus its solution can be calculated. As such, Lemma \ref{lem:nlp-sensitivity} provides a computational procedure to evaluate primal-dual solution sensitivity.

We now further analyze $QP(\bp,\bq)$; its first-order conditions are as follows:
\begin{subequations}\label{eqn:kkt}
  \begin{align}
    \bQ(\bp)\bxi + \bS(\bp)\bq + \bA(\bp)[\cA^{1}(\bp),:]^\top \bbeta &= \bzero\label{eqn:kkt-du}\\
    \bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq &= 0,\; i\in\cA^0(\bp)\label{eqn:kkt-pr-1}\\
    \bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq &\geq 0,\;i\in\cA^1(\bp)\setminus\cA^0(\bp)\label{eqn:kkt-pr-2}\\
    \bbeta[i] &\geq 0,\;i\in\cA^1(\bp)\setminus\cA^0(\bp)\\
    \left(\bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq \right)\bbeta[i]&=0,\; i\in\cA^1(\bp)\setminus\cA^0(\bp).\label{eqn:kkt-compl}
  \end{align}
\end{subequations}
Under SSOSC and LICQ for $P(\bp^\star)$ at $\bz^\star$, these conditions are necessary and sufficient for optimality. From the complementarity condition \eqref{eqn:kkt-compl}, one can observe that there exists $\cA^0(\bp)\subseteq\cA'(\bp,\bq)\subseteq \cA^1(\bp)$ such that:
\begin{subequations}\label{eqn:compl-explicit}
\begin{align}
  \bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq &= 0,\; i\in \cA'(\bp,\bq)\\
  \bbeta[i] &= 0,\; i\in \cA^1(\bp)\setminus \cA'(\bp,\bq).
\end{align}
\end{subequations}
are satisfied at $\bxi^\dag(\bp,\bq)$, $\bbeta^\dag(\bp,\bq)$. Thus, from \eqref{eqn:kkt}, \eqref{eqn:compl-explicit}, and $\bbeta[i]=0$ for $i\in\mathbb{I}_{[1,\bm]}\setminus \cA^1(\bp)$ (from Lemma \ref{lem:nlp-sensitivity}), we have:
\begin{align}\label{eqn:linear-form-0}
  \begin{aligned}
  \begin{bmatrix}
    \bQ(\bp)& \bA(\bp)[\cA'(\bp,\bq),:]^\top\\
    \bA(\bp)[\cA'(\bp,\bq),:]
  \end{bmatrix}
  \begin{bmatrix}
    \bxi\\
    \bbeta[\cA'(\bp,\bq)]
  \end{bmatrix} &= -
  \begin{bmatrix}
    \bS(\bp)\\  
    \bB(\bp)[\cA'(\bp,\bq),:]
  \end{bmatrix}\bq\\
  \bbeta [\mathbb{I}_{[1,\bm]}\setminus \cA'(\bp,\bq)] &= \bzero.
\end{aligned}
\end{align}
% The linear equation \eqref{eqn:linear-form-0} provides a relationship between $[\bxi^\dag(\bp,\bq);\bbeta^\dag(\bp,\bq)]$ and $\bq$; however, it does not provide an explicit relationship  because $\cA'(\bp,\bq)$ depends on $\bq$.
By rearranging $[\bxi^\dag(\bp,\bq);\bbeta^\dag(\bp,\bq)]$ one can obtain $\bzeta^\dag(\bp)=\{[\xi_i^\dag(\bp,\bq);\eta_i^\dag(\bp,\bq)]\}_{i\in\cV}$, where $\bxi^\dag(\bp,\bq)=\{\xi_i^\dag(\bp,\bq)\}_{i\in\cV}$, $\bbeta^\dag(\bp,\bq)=\{\eta_i^\dag(\bp,\bq)\}_{i\in\cV}$. To perform such rearrangement, we consider a permutation $\phi:\mathbb{I}_{[1,\bn]}\rightarrow\mathbb{I}_{[1,\bn]}$ that achieves $\bzeta[\phi(i)] = [\bxi;\bbeta][i]$. This permutation enables the following definition:
\begin{subequations}\label{eqn:Bs}
\begin{align}
  \cB^0(\bp)&:=\phi(\mathbb{I}_{[1,\br]}\cup(\cA^0(\bp)+\br)),\quad
                      \cB^1(\bp):=\phi(\mathbb{I}_{[1,\br]}\cup(\cA^1(\bp)+\br))\\
  \cB'(\bp,\bq)&:=\phi(\mathbb{I}_{[1,\br]}\cup(\cA'(\bp,\bq)+\br)).
\end{align}
\end{subequations}
Finally, using the notation in \eqref{eqn:Bs}, we obtain the following from \eqref{eqn:linear-form-0}:
\begin{subequations}\label{eqn:linear-form}
\begin{align}
  D_{\bq}\bz^\dag(\bp)[\cB'(\bp,\bq)] &= -\left(\bH(\bp)[\cB'(\bp,\bq),\cB'(\bp,\bq)]\right)^{-1}\bR(\bp)[\cB'(\bp,\bq),:] \bq,\\
  D_{\bq}\bz^\dag(\bp)[\mathbb{I}_{[1,\bn]}\setminus\cB'(\bp,\bq)] &= \bzero,\label{eqn:linear-form-b}
\end{align}
\end{subequations}
where:
\begin{align}\label{eqn:HR}
  \bH(\bp) &:= \nabla_{\bz\bz}\cL(\bz^\dag(\bp);\bp);\quad \bR(\bp) := \nabla_{\bz\bp}\cL(\bz^\dag(\bp);\bp).
\end{align}
Here, the nonsingularity of $\bH(\bp)[\cB'(\bp,\bq),\cB'(\bp,\bq)]$
% is guaranteed by the fact that $\bQ(\bp)$ is positive definite on the null-space of $\bA(\bp)[\cA^0(\bp),:]$. This
follows from LICQ, SSOSC, and \cite[Lemma 16.1]{nocedal2006numerical}.


\subsection{Nodal Sensitivity Result}\label{sec:nodal}
{We now establish the main nodal sensitivity result. First, we consider $\bH(\bp)$ and $\bR(\bp)$ as graph-structured matrices.} Specifically, we introduce the index set families $\cI:=\{I_i\}_{i\in\cV}$ and $\cK:=\{K_i\}_{i\in\cV}$with:
\begin{align}\label{eqn:ind-1}
  I_i &:= \mathbb{I}_{\sum_{j\in \cV,j<i}n_j+[1,n_i]},\quad
  K_i := \mathbb{I}_{\sum_{j\in \cV,j<i}l_j+[1,l_i]},
\end{align}
and impose graph structures to $\bH(\bp)$ and $\bR(\bp)$ with $(\cG,\cI,\cI)$ and $(\cG,\cI,\cK)$, respectively. Note that $\cI$ and $\cK$ partition $\mathbb{I}_{[1,\bn]}$ and $\mathbb{I}_{[1,\bl]}$, respectively. For $i,j\in\cV$,
\begin{subequations}\label{eqn:HRij}
\begin{align}
  H_{ij}(\bp)&:=\nabla^2_{z_iz_j}\cL(\bz^\dag(\bp);\bp)=(\bH(\bp))_{[i][j]}\\
  R_{ij}(\bp)&:=\nabla^2_{z_ip_j}\cL(\bz^\dag(\bp);\bp)=(\bR(\bp))_{[i][j]}.
\end{align}
\end{subequations}
{We now can observe that $\bH(\bp)$ and $\bR(\bp)$ have bandwidth not greater than two. In other words, if $d_\mathcal{G}(i,j)> 2$, $\nabla_{z_i z_j}\mathcal{L}(\bz;\bp)=0$ and $\nabla_{z_i p_j}\mathcal{L}(\bz;\bp)=0$. This is because in the graph-structured nonlinear programming setting in (1.1), we have assumed that the nodal objective and constraint functions are only dependent on the variables that are within the closed neighborhood of the associated node.}
% The reason that the bandwidth may be greater than one is as follows. Suppose that $\cV=\{1,2,3\}$ and $\cE=\{\{1,2\},\{2,3\}\}$; then the constraints at node $2$ can be coupled with variables/data at node $1$ and $3$. This produces potential coupling between the variables that are within distance $2$ can have potential coupling.

The submatrices of $\bH(\bp)$ and $\bR(\bp)$ are also graph-structured. In particular, $\bH(\bp)[\cB,\cB]$ and $\bR(\bp)[\cB,:]$ with $\cB\subseteq \mathbb{I}_{[1,\bn]}$ have bandwidth not greater than two induced by $(\cG,\cI^\cB,\cI^\cB)$ and $(\cG,\cI^\cB,\cK)$, where $\cI^\cB:=\{I_i\cap\cB\}_{i\in\cV}$. We thus see that \eqref{eqn:linear-form} involves the inverse of a {graph-induced banded} matrix. By combining Theorem \ref{thm:inv} and Lemma \ref{lem:nlp-sensitivity}, we obtain the following result.

