    \begin{align}
      QP(\bp,\bq):\quad\min_{\bxi}\;&\frac{1}{2}\bxi^\top\bQ(\bp)\bxi + \bxi^\top\bS(\bp)\bq,\label{eqn:nlp-sensitivity-0-obj}\\
      \st\;&\bA(\bp)[i,:]^\top\bxi + \bB(\bp)[i,:]\bq = 0,\;i\in \cA^0(\bp),\; (\bbeta[i])\\
                   &\bA(\bp)[i,:]^\top\bxi + \bB(\bp)[i,:]\bq \geq 0,\;i\in \cA^1(\bp)\setminus \cA^0(\bp),\; (\bbeta[i])
    \end{align}      
  \end{subequations}
  and $\bbeta^\dag(\bp,\bq)[\mathbb{I}_{[1,\bm]}\setminus\cA^1(\bp)]=\bzero$ (i.e., the free dual variables are fixed to zero); here,
  \begin{subequations}\label{eqn:AAQA}
    \begin{align}
      \cA^0(\bp)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\dag(\bp))[i]=0,\;\by^\dag(\bp)[i]\neq 0\}\\
      \cA^1(\bp)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\dag(\bp))[i]=0\}\\
      \bQ(\bp)&:=\nabla_{\bx\bx}\cL(\bz^\dag(\bp);\bp);\quad \bS(\bp):=\nabla_{\bx\bp}\cL(\bz^\dag(\bp);\bp)\\
      \bA(\bp)&:=\nabla_{\bx}\bc(\bx^\dag(\bp);\bp);\quad \bB(\bp):=\nabla_{\bp}\bc(\bx^\dag(\bp);\bp).
    \end{align}
  \end{subequations}
  Moreover, a unique primal-dual solution of $QP(\bp,\bq)$ exists for any $\bp\in\mathbb{P}$ and $\bq\in\mathbb{R}^{\bl}$; thus, $\bxi^\dag(\cdot,\cdot)$ and $\bbeta^\dag(\cdot,\cdot)$ are well-defined.
\end{lemma}

\begin{proof}
  The results in \cite[Theorem 2G.8]{dontchev2009implicit} ensure semidifferentiability (which guarantees continuity) of the solution of the first-order optimality conditions for $P(\bp)$ over a certain neighborhood of $\bp^\star$. Furthermore, \cite[Theorem 2G.9]{dontchev2009implicit} establishes that over a certain neighborhood $\mathbb{P}$, the solution mapping of the generalized equation (GE) satisfies SSOSC and LICQ; that is, within $\mathbb{P}$, the solution mapping for the GE is the solution mapping for $P(\bp)$ at which SSOSC and LICQ are satisfied. Moreover, by \cite[Theorem 2G.8]{dontchev2009implicit}, the one-sided directional derivative of the solution mapping for the GE (which exists for any direction $\bq\in\mathbb{R}^{\bl}$ by semidifferentiability \cite[Theorem 2D.1]{dontchev2009implicit}) can be evaluated by using the linearized GE. The linear GE corresponds to the first-order optimality conditions for $QP(\bp,\bq)$ (see \cite[Equation (35)]{dontchev2009implicit}); here, the first-order conditions are necessary and sufficient conditions for the optimality due to the convexity $QP(\bp,\bq)$ (guaranteed by SSOSC and LICQ of $\bz^\star$ for the original problem). As such, the one-sided directional derivative of the solution mapping for $P(\bp)$ can be evaluated by solving $QP(\bp,\bq)$. Finally, the strong regularity of the GE at $\bz^\star$ guarantees that there exists a unique solution of the linearized GE, which in turn guarantees the existence of a unique solution of $QP(\bp,\bq)$.  
\end{proof}

\begin{lemma}\label{lem:dder}
  Suppose Assumptions \ref{ass:c2}, \ref{ass:regularity} hold, and suppose that, for given $\bp\in\mathbb{P}$ (defined in Lemma \ref{lem:nlp-sensitivity}) and $\bq:=\{q_i\}_{i\in \cV}\in\mathbb{R}^{\bl}$, we have $\osigma_{\bH}(\bp,\bq)$, $\osigma_{\bR}(\bp,\bq)$, and $\usigma_{\bH}(\bp,\bq)$ such that:
  \begin{subequations}\label{eqn:dder-0}
  \begin{align}
    \osigma_{\bH}(\bp,\bq)&\geq \osigma(\bH(\bp)[\cB'(\bp,\bq),\cB'(\bp,\bq)])\\
    \osigma_{\bR}(\bp,\bq)&\geq \osigma(\bR(\bp)[\cB'(\bp,\bq),:])\\
    0<\usigma_{\bH}(\bp,\bq)&\leq \usigma(\bH(\bp)[\cB'(\bp,\bq),\cB'(\bp,\bq)]);\label{eqn:dder-0-c}
  \end{align}
\end{subequations}
then the following holds for any $i\in \cV$:
  \begin{align*}
    \Vert D_{\bq} z^\dag_i(\bp,\bq)\Vert\leq \sum_{j\in \cV}\frac{\osigma_{\bH}(\bp,\bq)\osigma_{\bR}(\bp,\bq)}{\usigma_{\bH}(\bp,\bq)^2}\left(\frac{\osigma_{\bH}(\bp,\bq)^2-\usigma_{\bH}(\bp,\bq)^2}{\osigma_{\bH}(\bp,\bq)^2+\usigma_{\bH}(\bp,\bq)^2}\right)^{\left\lceil \frac{d_\cG(i,j)}{4}-1\right\rceil_+}\Vert q_j\Vert.
  \end{align*}
\end{lemma}

\begin{proof}
  {\blue For simplicity, we denote $\cB'(\bp,\bq)$, $\osigma_{\bH}(\bp,\bq)$, $\osigma_{\bR}(\bp,\bq)$, $\usigma_{\bH}(\bp,\bq)$ by $\cB'$, $\osigma_{\bH}$, $\osigma_{\bR}$, $\usigma_{\bH}$}. From that $\bH(\bp)[\cB',\cB']$ is always nonsingular, we have that $\usigma_{\bH}(\bp,\bq)$ satisfying \eqref{eqn:dder-0-c} always exists. By inspecting the block structure of \eqref{eqn:linear-form} we obtain:
  \begin{align}\label{eqn:nlp-sensitivity-1}
    D_{\bq}\bz^\dag(\bp)[I_i\cap\cB'] &= \sum_{j\in \cV} -((\bH(\bp)[\cB',\cB'])^{-1}\bR(\bp)[\cB',:])_{[i][j]} q_j,
  \end{align}
  where $\cI^{\cB'}:=\{I_i\cap{\cB'}\}_{i\in \cV}$ and $\cK:=\{K_i\}_{i\in \cV}$ (defined in \eqref{eqn:ind-1}) are used for index sets. We have already established that $\bH(\bp)[\cB',\cB']$ has bandwidth not greater than two, induced by $(\cG,\cI^{\cB'},\cI^{\cB'})$ and that $\bR(\bp)[\cB',:]$ has bandwidth not greater than two, induced by $(\cG,\cI^{\cB'},\cK)$. By applying Theorem \ref{thm:inv}, we obtain:
  \begin{align}\label{eqn:nlp-sensitivity-2}\blue
    \Vert((\bH(\bp)[\cB',\cB'])^{-1}\bR(\bp)[\cB',:])_{[i][j]}\Vert\leq \frac{\osigma_{\bH}\osigma_{\bR}}{\usigma_{\bH}^2}\left(\frac{\osigma_{\bH}^2-\usigma_{\bH}^2}{\osigma_{\bH}^2+\usigma_{\bH}^2}\right)^{\left\lceil \frac{d_\cG(i,j)}{4}-1\right\rceil_+} .
  \end{align}
  Now note that
  $\Vert D_{\bq}z^\dag_i(\bp)\Vert \leq \Vert D_{\bq}\bz^\dag(\bp)[I_i\cap\cB'] \Vert  + \Vert D_{\bq}\bz^\dag(\bp)[I_i\setminus\cB']\Vert$,
  and recall from \eqref{eqn:linear-form-b} that $D_{\bq}\bz^\dag(\bp)[I_i\setminus\cB'] =\bzero$. Hence, by applying \eqref{eqn:nlp-sensitivity-2} to \eqref{eqn:nlp-sensitivity-1}, and applying triangle inequality, we obtain the desired result.
\end{proof}

\begin{proof}
  From the continuity of $\bz^\dag(\cdot)$ in the neighborhood of $\bp^\star$ and the continuity of $\bc(\cdot,\cdot)$ in the neighborhood of $[\bz^\star;\bp^\star]$, there exists a neighborhood $\widetilde{\mathbb{P}}\subseteq\mathbb{P}$ of $\bp^\star$ such that, for $\bp\in\widetilde{\mathbb{P}}$ and $i\in\mathbb{I}_{[1,\bm]}$, $\bc(\bx^\star)[i] > 0\Rightarrow\bc(\bx^\dag(\bp))[i] > 0$ and $\by^\star[i] \neq 0\Rightarrow\by^\dag(\bp)[i] \neq 0$. These conditions and complementarity slackness imply that for $\bp\in\widetilde{\mathbb{P}}$, we have $\cA^0(\bp^\star)\subseteq\cA^0(\bp)$ and $\cA^1(\bp)\subseteq\cA^1(\bp^\star)$; that is, $\cB^0(\bp^\star)\subseteq\cB^0(\bp)$ and $\cB^1(\bp)\subseteq\cB^1(\bp^\star)$. This and $\cB^0(\bp)\subseteq\cB'(\bp,\bq)\subseteq\cB^1(\bp)$ yields:
  \begin{subequations}\label{eqn:main-0}
  \begin{align}
    \osigma({\bH}(\bp)[\cB'(\bp,\bq),\cB'(\bp,\bq)])&\leq \oosigma_{\bH}(\bp)\\
    \osigma({\bR}(\bp)[\cB'(\bp,\bq),:])&\leq \oosigma_{\bR}(\bp)\\
    \usigma({\bH}(\bp)[\cB'(\bp,\bq),\cB'(\bp,\bq)])&\geq \uusigma_{\bH}(\bp).
  \end{align}
\end{subequations}
  By the twice-continuous differentiability of $\cL(\cdot,\cdot)$ and the continuity of $\bz^\dag(\cdot)$, we have that $\bH(\cdot)$ is continuous. The same holds true for its submatrices: $\bH(\cdot)[\cB,\cB]$ with $\cB^0(\bp^\star)\subseteq \cB\subseteq \cB^1(\bp^\star)$. From the continuity of singular values with respect to its entries \cite[Corollary 8.6.2]{golub2012matrix}, we have that $\osigma(\bH(\cdot)[\cB,\cB])$ and $\usigma(\bH(\cdot)[\cB,\cB])$ are continuous for any $\cB^0(\bp^\star)\subseteq \cB\subseteq \cB^1(\bp^\star)$; accordingly, since a maximum and a minimum of a fixed and finite number of continuous functions is continuous, we have that $\oosigma_{\bH}(\bp)$, $\oosigma_{\bR}(\bp)$, $\uusigma_{\bH}(\bp)$ are continuous with respect to $\bp$ in $\widetilde{\mathbb{P}}$. Thus, there exists a convex neighborhood $\mathbb{P}_{\epsilon}\subseteq\widetilde{\mathbb{P}}$ of $\bp^\star$ wherein the following are satisfied:
  \begin{subequations}\label{eqn:main-1}
  \begin{align}
    \frac{\oosigma_{\bH}(\bp)\oosigma_{\bR}(\bp)}{\uusigma_{\bH}(\bp)^2} &\leq
    \frac{\oosigma_{\bH}(\bp^\star)\oosigma_{\bR}(\bp^\star)}{\uusigma_{\bH}(\bp^\star)^2}+\epsilon\\
    \frac{\oosigma_{\bH}(\bp)^2-\uusigma_{\bH}(\bp)^2}{\oosigma_{\bH}(\bp)^2+\uusigma_{\bH}(\bp)^2}&\leq
    \frac{\oosigma_{\bH}(\bp^\star)^2-\uusigma_{\bH}(\bp^\star)^2}{\oosigma_{\bH}(\bp^\star)^2+\uusigma_{\bH}(\bp^\star)^2}+\epsilon.
  \end{align}
\end{subequations}
Here, note that $\uusigma_{\bH}(\bp^\star)>0$ because $\usigma(\bH[\cB,\cB])>0$ holds for any $\cB^0(\bp^\star)\subseteq\cB\subseteq\cB^1(\bp^\star)$. By applying \eqref{eqn:main-0} and \eqref{eqn:main-1} to Lemma \ref{lem:dder}, we obtain:
\begin{align}\label{eqn:main-2}
  \Vert D_{\bq} z^\dag_i(\bp)\Vert&\leq \sum_{j\in \cV}\left(\frac{\oosigma_{\bH}(\bp^\star)\oosigma_{\bR}(\bp^\star)}{\uusigma_{\bH}(\bp^\star)^2}+\epsilon\right)\left(\frac{\oosigma_{\bH}(\bp^\star)^2-\uusigma_{\bH}(\bp^\star)^2}{\oosigma_{\bH}(\bp^\star)^2+\uusigma_{\bH}(\bp^\star)^2}+\epsilon\right)^{\left\lceil \frac{d_\cG(i,j)}{4}-1\right\rceil_+}\Vert q_j\Vert\nonumber\\
  &\leq \sum_{j\in \cV}\left(\frac{\osigma_{\bH}\osigma_{\bR}}{\usigma_{\bH}^2}+\epsilon\right)\left(\frac{\osigma_{\bH}^2-\usigma_{\bH}^2}{\osigma_{\bH}^2+\usigma_{\bH}^2}+\epsilon\right)^{\left\lceil \frac{d_\cG(i,j)}{4}-1\right\rceil_+}\Vert q_j\Vert\nonumber\\
  &\leq \sum_{j\in \cV}\Upsilon\rho^{\left\lceil \frac{d_\cG(i,j)}{4}-1\right\rceil_+}\Vert q_j\Vert,
\end{align}
for any $\bp\in\mathbb{P}_{\epsilon}$ and $\bq\in\mathbb{R}^{\bl}$. Finally, since we have chosen $\mathbb{P}_\epsilon$ to be convex, for any $\bp,\bp'\in\mathbb{P}_{\epsilon}$, the line segment between $\bp,\bp'$ is within $\mathbb{P}_{\epsilon}$. Thus, we have:
\begin{align*}
  \Vert z^\dag_i(\bp)-z^\dag_i(\bp')\Vert
  % &\leq\Vert \int_{0}^1 D_{\bp'-\bp}z^\dag_i ((1-t)\bp+t\bp')dt\Vert\\
    &\leq \int_{0}^1\Vert D_{\bp'-\bp}z^\dag_i ((1-t)\bp+t\bp')\Vert dt \leq \sum_{j\in \cV}\Upsilon\rho^{\left\lceil \frac{d_\cG(i,j)}{4}-1\right\rceil_+}\Vert p_j-p'_j\Vert,
\end{align*}
where the first inequality is from Newton-Leibniz and triangle inequality for integrals, and the last inequality follows from \eqref{eqn:main-2}.
\end{proof}

