\begin{theorem}[Exponential Decay of Sensitivity (EDS)]\label{thm:main}
  Under Assumptions \ref{ass:c2}, \ref{ass:regularity}, and for given $\epsilon>0$, $\osigma_{\bH}\geq\oosigma_{\bH}(\bp^\star)$, $\osigma_{\bR}\geq\oosigma_{\bR}(\bp^\star)$, and $0<\usigma_{\bH}\leq\uusigma_{\bH}(\bp^\star)$, where
  \begin{subequations}\label{eqn:sigmas}
    \begin{align}
      \oosigma_{\bH}(\bp)&:=\max\{\osigma(\bH(\bp)[\cB,\cB]):\cB^0(\bp^\star)\subseteq\cB\subseteq\cB^1(\bp^\star)\}\\
      \oosigma_{\bR}(\bp)&:=\max\{\osigma(\bR(\bp)[\cB,:]):\cB^0(\bp^\star)\subseteq\cB\subseteq\cB^1(\bp^\star)\}\\
      \uusigma_{\bH}(\bp)&:=\min\{\usigma(\bH(\bp)[\cB,\cB]):\cB^0(\bp^\star)\subseteq\cB\subseteq\cB^1(\bp^\star)\},
    \end{align}
  \end{subequations}
  there exists a neighborhood $\mathbb{P}_{\epsilon}$ of $\bp^\star$ such that the following holds for any $\bp,\bp'\in\mathbb{P}_{\epsilon}$:
  \begin{align}\label{eqn:main}
      &\Vert z^\dag_i(\bp)-z^\dag_i(\bp')\Vert 
      \leq \sum_{j\in \cV} \Upsilon\rho^{\left\lceil \frac{d_\cG(i,j)}{4}-1\right\rceil_+} \Vert p_j-p'_j\Vert,\quad i\in \cV,
  \end{align}
with $\Upsilon :=\dfrac{\osigma_{\bH}\osigma_{\bR}}{{\usigma}_{\bH}^2}+\epsilon$ and $\rho:=\dfrac{\osigma_{\bH}^2-{\usigma}_{\bH}^2}{\osigma_{\bH}^2+{\usigma}_{\bH}^2}+\epsilon$.
\end{theorem}

