\begin{definition}[Graph Distance and Diameter]\label{def:distance}
  The distance $d_\cG(i,j)$ between nodes $i,j\in \cV$ on graph $\cG=(\cV,\cE)$ is the number of edges in the shortest path connecting them; {if a shortest path does not exist, the distance is $+\infty$}. Furthermore, the diameter $D_\cG$ of $\cG$ is the longest distance between any pair of nodes in $\cV$.
\end{definition}

\begin{proposition}\label{prop:metric}
  The distance $d_\cG:\cV\times \cV \rightarrow \mathbb{I}_{\geq 0}{\cup\{\infty\}}$ is a metric on $\cV$; that is, (a) $d_\cG(i,j)\geq 0$ for any $i,j\in \cV$; (b) $i=j$ if and only if $d_\cG(i,j)=0$; (c) $d_\cG(i,j)=d_\cG(j,i)$ for any $i,j\in \cV$; (d) $d_\cG(i,j)\leq d_\cG(i,k)+d_\cG(k,j)$ for any $i,j,k\in \cV$.
\end{proposition}
The proof of this result is straightforward and thus omitted. {Note that the shortest path does not exist when the graph is not connected. }

\begin{definition}[Graph-Induced Bandwidth]\label{def:bandwidth}
  Consider a matrix $X\in\mathbb{R}^{m\times n}$, a graph $\cG=(\cV,\cE)$, and index sets $\cI=\{I_i\}_{i\in \cV}$, $\cJ=\{J_i\}_{i\in \cV}$ that partition $\mathbb{I}_{[1,m]}$ and $\mathbb{I}_{[1,n]}$, respectively. Matrix $X$ is said to have bandwidth $B$ induced by $(\cG,\cI,\cJ)$, if $B$ is the smallest nonnegative integer such that $X_{[i][j]}=\bzero$ for any $i,j\in \cV$ with $d_\cG(i,j)> B$, where $X_{[i][j]}:=X[I_i,J_j]$.
\end{definition}

\begin{lemma}\label{lem:bandwidth}
  Consider $X\in\mathbb{R}^{m\times n}$ with bandwidth not greater than $B_X$ induced by $(\cG,\cI,\cJ)$; we have that:
  (a) $X^\top$ has bandwidth not greater than $B_X$ induced by $(\cG,\cJ,\cI)$;
  (b) if $Y\in\mathbb{R}^{m\times n}$ has bandwidth not greater than $B_Y$ induced by $(\cG,\cI,\cJ)$, then $X+Y$ has bandwidth not greater than $\max(B_X,B_Y)$ induced by $(\cG,\cI,\cJ)$;
  (c) if $W\in\mathbb{R}^{n\times k}$ has bandwidth not greater than $B_W$ induced by $(\cG,\cJ,\cK)$, then $XW$ has bandwidth not greater than $B_X+B_W$ induced by $(\cG,\cI,\cK)$.
\end{lemma}

\begin{theorem}\label{thm:inv}
  Consider a nonsingular matrix $X\in\mathbb{R}^{n\times n}$ with bandwidth not greater than $B_X\geq 1$ induced by $(\cG,\cK,\cP)$, $Y\in\mathbb{R}^{n\times m}$ with bandwidth not greater than $B_Y$ induced by $(\cG, \cK,\cJ)$, and $W\in\mathbb{R}^{\ell\times n}$ with bandwidth not greater than $B_W$ induced by $(\cG, \cI,\cP)$; for constants $\osigma_X\geq \osigma(X)$, $\osigma_Y\geq \osigma(Y)$, $\osigma_W\geq \osigma(W)$, and $0<\usigma_X\leq \usigma(X)$, the following holds:
  \begin{align}\label{eqn:inv}
    \Vert (WX^{-1}Y)_{[i][j]}\Vert \leq
    \frac{\osigma_X\osigma_Y\osigma_W}{\usigma_X^2}\left(\frac{\osigma_X^2-\usigma_X^2}{\osigma_X^2+\usigma_X^2}\right)^{\left\lceil \frac{d_\cG(i,j)-B_X-B_Y-B_W}{2B_X}\right\rceil_+} ,\quad i,j\in \cV,
  \end{align}
  where $(WX^{-1}Y)_{[i][j]}:=(WX^{-1}Y)[I_i,J_j]$ and $\lceil\cdot\rceil_+$ is the smallest non-negative integer that is greater than or equal to the argument.
\end{theorem}

\begin{proof}
  By definition of singular values and the assumptions on $\osigma_X$, $\osigma_Y$ , $\osigma_W$, and $\usigma_X$, we have $\usigma_X^2 \bI \preceq\usigma(X)^2 \bI \preceq X X^\top\preceq  \osigma(X)^2\bI\preceq\osigma_X^2 \bI $. From this, one can obtain:
 \begin{align}\label{eqn:factor}
   \frac{\usigma_X^2-\osigma_X^2}{\usigma_X^2+\osigma_X^2} \bI\preceq \bI-\frac{2}{\usigma_X^2+\osigma_X^2}XX^\top
   \preceq \frac{-\usigma_X^2+\osigma_X^2}{\usigma_X^2+\osigma_X^2}\bI.
 \end{align}
 By Lemma \ref{lem:bandwidth}(c), $XX^\top$ has bandwidth not greater than $2B_X$ induced by $(\cG,\cK,\cK)$. From the nonsingularity of $XX^\top$, we obtain the following:
 \begin{subequations}\label{eqn:key-1}
   \begin{align}
     WX^{-1}Y &= \frac{2}{\usigma_X^2+\osigma_X^2} WX^\top \left(\frac{2}{\usigma_X^2+\osigma_X^2}XX^\top \right)^{-1}Y\\
   % &= \frac{2}{\usigma_X^2+\osigma_X^2} WX^\top \left(\bI-\left(\bI-\frac{2}{\usigma_X^2+\osigma_X^2}XX^\top \right)\right)^{-1} Y\\
     &= \frac{2}{\usigma_X^2+\osigma_X^2}WX^\top \left(\sum_{q=0}^\infty \left(\bI-\frac{2}{\usigma_X^2+\osigma_X^2}XX^\top \right)^q\right)Y,\label{eqn:key-1-c}\\
     &=\frac{2}{\usigma_X^2+\osigma_X^2} \sum_{q=0}^\infty WX^\top\left(\bI-\frac{2}{\usigma_X^2+\osigma_X^2}XX^\top \right)^q Y.
 \end{align}
 \end{subequations}
 Here the second equality follows from \cite[Corollary 5.6.16]{horn2012matrix} and \eqref{eqn:factor}, and the last equality follows from the fact that the series in \eqref{eqn:key-1-c} converges (due to \eqref{eqn:factor}). Furthermore, from Lemma \ref{lem:bandwidth}, we see that $WX^\top\left(\bI-\frac{2}{\usigma_X^2+\osigma_X^2}XX^\top \right)^q Y$ has bandwidth not greater than $(2q+1)B_X +B_Y+B_W$, induced by $(\cG,\cI,\cJ)$. By extracting submatrices $(\cdot)[I_i,J_j]$ from \eqref{eqn:key-1}, we obtain:
  \begin{align*}
    (WX^{-1}Y)_{[i][j]}&=\frac{2}{\usigma_X^2+\osigma_X^2} \sum_{q=q_0(i,j)}^\infty \left(WX^\top\left(\bI-\frac{2XX^\top}{\usigma_X^2+\osigma_X^2} \right)^q Y\right)_{[i][j]}
  \end{align*}
  where $q_0(i,j):=\left\lceil \frac{d_\cG(i,j)-B_X-B_Y-B_W}{2B_X}\right\rceil_+$; the summation over $q=0,\cdots, q_0(i,j)-1$ is zero because such $q$ satisfy $(2q+1)B_X+B_Y+B_W< d_\cG(i,j)$. Using the triangle inequality and the fact that the matrix norm of a submatrix is smaller than that of the original matrix,
  \begin{align}\label{eqn:Hbound}
    \Vert (WX^{-1}Y)_{[i][j]} \Vert &\leq \frac{2}{\usigma_X^2+\osigma_X^2} \sum_{q=q_0(i,j)}^\infty \left\Vert WX^\top\left(\bI-\frac{2XX^\top}{\usigma_X^2+\osigma_X^2}\right)^q Y\right\Vert\\
    &\leq \frac{2}{\usigma_X^2+\osigma_X^2} \sum_{q=q_0(i,j)}^\infty \osigma_W\osigma_X\left(\frac{\osigma_X^2-\usigma_X^2}{\osigma_X^2+\usigma_X^2}\right)^q \osigma_Y\nonumber\\
    &\leq \frac{\osigma_X\osigma_Y\osigma_W}{\usigma_X^2}\left(\frac{\osigma_X^2-\usigma_X^2}{\osigma_X^2+\usigma_X^2}\right)^{\left\lceil \frac{d_\cG(i,j)-B_X-B_Y-B_W}{2B_X}\right\rceil_+} .\nonumber
  \end{align}
  The second inequality follows from the submultiplicativity of the matrix norm and \eqref{eqn:factor}; and the last inequality follows from the summation of geometric series. 
\end{proof}

