\begin{assumption}[Twice Continuous Differentiability of Functions]\label{ass:c2}
  The functions $\bff:\mathbb{R}^{\br}\times \mathbb{R}^{\bl}\rightarrow \mathbb{R}$ and $\bc:\mathbb{R}^{\br}\times \mathbb{R}^{\bl}\rightarrow \mathbb{R}^{\bm}$ are twice continuously differentiable in the neighborhood of $[\bx^\star;\bp^\star]$.
\end{assumption}

\begin{assumption}[Regularity of Solution]\label{ass:regularity}
  The base solution $\bz^\star$ satisfies SSOSC and LICQ for $P(\bp^\star)$ with base data $\bp^\star$.
\end{assumption}

We recall that SSOSC requires positive definiteness of the reduced Hessian of the Lagrangian at $\bz^\star$. The reduced Hessian is the Hessian projected on the null space defined by equality constraints and active inequality constraints with nonzero duals. LICQ requires that the constraint Jacobian defined by equality and active inequality constraints are linearly independent at $\bz^\star$. These requirements are stated as: 
\begin{align*}
  ReH(\nabla^2_{\bx\bx}\cL(\bz^\star;\bp^\star),\nabla_{\bx}\bc(\bx^\star;\bp^\star)[\cA^0(\bp^\star),:]) &\succ \bzero\tag{SSOSC}\\
  \usigma(\nabla_{\bx}\bc(\bx^\star;\bp^\star)[\cA^1(\bp^\star),:]) &> 0 \tag{LICQ}.
\end{align*}
Here, $\cL(\bz;\bp) := \bff(\bx;\bp)-\by^\top \bc(\bx;\bp)$ is the Lagrange function, $ReH(H,A):=Z^\top HZ$ is the reduced Hessian, where $Z$ is a null-space matrix of $A$, and

\begin{align}\label{eqn:active-set-defs}
  \cA^0(\bp^\star)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\star)[i]=0,\;\by^\star[i]\neq 0\}\\
  \cA^1(\bp^\star)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\star)[i]=0\},
\end{align}
where $\cA^E$ and $\cA^I$ are the set of equality and inequality constraint indices. Hereafter, we call a solution of gsNLP regular if the solution satisfies SSOSC and LICQ. Note that SSOSC and LICQ are standard assumptions used in NLP sensitivity theory \cite{robinson1980strongly}. We now state the classical sensitivity result.

\begin{lemma}\label{lem:nlp-sensitivity}
  Under Assumptions \ref{ass:c2}, \ref{ass:regularity}, there exist neighborhoods $\mathbb{P}\subseteq\mathbb{R}^{\bl}$ of $\bp^\star$ and $\bbZ\subseteq\mathbb{R}^{\bn}$ of $\bz^\star$ and a continuous function $\bz^\dag:\mathbb{P}\rightarrow \bbZ$ such that $\bz^\dag(\bp)$ is a primal-dual solution of $P(\bp)$ that satisfies SSOSC and LICQ. Furthermore, for any $\bq:=\{q_i\}_{i\in \cV}\in\mathbb{R}^{\bl}$, the one-sided directional derivative of $\bz^\dag(\cdot)$ is given by:
  \begin{align*}
    D_{\bq} \bz^\dag(\bp)&:=\lim_{h\searrow 0}\frac{\bz^\dag(\bp+\bq h)-\bz^\dag(\bp)}{h}; \label{eqn:one-sided-DD}
  \end{align*}
  with $D_{\bq}\bx^\dag(\bp) = \bxi^\dag(\bp,\bq)$, $D_{\bq}\by^\dag(\bp,\bq) = \bbeta^\dag(\bp,\bq)$, where $(\bxi^\dag(\bp,\bq),\bbeta^\dag(\bp,\bq)[\cA^1(\bp)])$ is a primal-dual solution of the quadratic program:
  \begin{subequations}\label{eqn:nlp-sensitivity-0}
    \begin{align}
      QP(\bp,\bq):\quad\min_{\bxi}\;&\frac{1}{2}\bxi^\top\bQ(\bp)\bxi + \bxi^\top\bS(\bp)\bq,\label{eqn:nlp-sensitivity-0-obj}\\
      \st\;&\bA(\bp)[i,:]^\top\bxi + \bB(\bp)[i,:]\bq = 0,\;i\in \cA^0(\bp),\; (\bbeta[i])\\
                   &\bA(\bp)[i,:]^\top\bxi + \bB(\bp)[i,:]\bq \geq 0,\;i\in \cA^1(\bp)\setminus \cA^0(\bp),\; (\bbeta[i])
    \end{align}      
  \end{subequations}
  and $\bbeta^\dag(\bp,\bq)[\mathbb{I}_{[1,\bm]}\setminus\cA^1(\bp)]=\bzero$ (i.e., the free dual variables are fixed to zero); here,
  \begin{subequations}\label{eqn:AAQA}
    \begin{align}
      \cA^0(\bp)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\dag(\bp))[i]=0,\;\by^\dag(\bp)[i]\neq 0\}\\
      \cA^1(\bp)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\dag(\bp))[i]=0\}\\
      \bQ(\bp)&:=\nabla_{\bx\bx}\cL(\bz^\dag(\bp);\bp);\quad \bS(\bp):=\nabla_{\bx\bp}\cL(\bz^\dag(\bp);\bp)\\
      \bA(\bp)&:=\nabla_{\bx}\bc(\bx^\dag(\bp);\bp);\quad \bB(\bp):=\nabla_{\bp}\bc(\bx^\dag(\bp);\bp).
    \end{align}
  \end{subequations}
  Moreover, a unique primal-dual solution of $QP(\bp,\bq)$ exists for any $\bp\in\mathbb{P}$ and $\bq\in\mathbb{R}^{\bl}$; thus, $\bxi^\dag(\cdot,\cdot)$ and $\bbeta^\dag(\cdot,\cdot)$ are well-defined.
\end{lemma}

\begin{proof}
  The results in \cite[Theorem 2G.8]{dontchev2009implicit} ensure semidifferentiability (which guarantees continuity) of the solution of the first-order optimality conditions for $P(\bp)$ over a certain neighborhood of $\bp^\star$. Furthermore, \cite[Theorem 2G.9]{dontchev2009implicit} establishes that over a certain neighborhood $\mathbb{P}$, the solution mapping of the generalized equation (GE) satisfies SSOSC and LICQ; that is, within $\mathbb{P}$, the solution mapping for the GE is the solution mapping for $P(\bp)$ at which SSOSC and LICQ are satisfied. Moreover, by \cite[Theorem 2G.8]{dontchev2009implicit}, the one-sided directional derivative of the solution mapping for the GE (which exists for any direction $\bq\in\mathbb{R}^{\bl}$ by semidifferentiability \cite[Theorem 2D.1]{dontchev2009implicit}) can be evaluated by using the linearized GE. The linear GE corresponds to the first-order optimality conditions for $QP(\bp,\bq)$ (see \cite[Equation (35)]{dontchev2009implicit}); here, the first-order conditions are necessary and sufficient conditions for the optimality due to the convexity $QP(\bp,\bq)$ (guaranteed by SSOSC and LICQ of $\bz^\star$ for the original problem). As such, the one-sided directional derivative of the solution mapping for $P(\bp)$ can be evaluated by solving $QP(\bp,\bq)$. Finally, the strong regularity of the GE at $\bz^\star$ guarantees that there exists a unique solution of the linearized GE, which in turn guarantees the existence of a unique solution of $QP(\bp,\bq)$.  
\end{proof}

\begin{subequations}\label{eqn:AAQA}
  \begin{align}
    \cA^0(\bp)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\dag(\bp))[i]=0,\;\by^\dag(\bp)[i]\neq 0\}\\
    \cA^1(\bp)&:=\cA^E\cup\{i\in\cA^I:\bc(\bx^\dag(\bp))[i]=0\}\\
    \bQ(\bp)&:=\nabla_{\bx\bx}\cL(\bz^\dag(\bp);\bp);\quad \bS(\bp):=\nabla_{\bx\bp}\cL(\bz^\dag(\bp);\bp)\\
    \bA(\bp)&:=\nabla_{\bx}\bc(\bx^\dag(\bp);\bp);\quad \bB(\bp):=\nabla_{\bp}\bc(\bx^\dag(\bp);\bp).
  \end{align}
\end{subequations}

We now further analyze $QP(\bp,\bq)$; its first-order conditions are as follows:
\begin{subequations}\label{eqn:kkt}
  \begin{align}
    \bQ(\bp)\bxi + \bS(\bp)\bq + \bA(\bp)[\cA^{1}(\bp),:]^\top \bbeta &= \bzero\label{eqn:kkt-du}\\
    \bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq &= 0,\; i\in\cA^0(\bp)\label{eqn:kkt-pr-1}\\
    \bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq &\geq 0,\;i\in\cA^1(\bp)\setminus\cA^0(\bp)\label{eqn:kkt-pr-2}\\
    \bbeta[i] &\geq 0,\;i\in\cA^1(\bp)\setminus\cA^0(\bp)\\
    \left(\bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq \right)\bbeta[i]&=0,\; i\in\cA^1(\bp)\setminus\cA^0(\bp).\label{eqn:kkt-compl}
  \end{align}
\end{subequations}
Under SSOSC and LICQ for $P(\bp^\star)$ at $\bz^\star$, these conditions are necessary and sufficient for optimality. From the complementarity condition \eqref{eqn:kkt-compl}, one can observe that there exists $\cA^0(\bp)\subseteq\cA'(\bp,\bq)\subseteq \cA^1(\bp)$ such that:

Under SSOSC and LICQ for $P(\bp^\star)$ at $\bz^\star$, these conditions are necessary and sufficient for optimality. From the complementarity condition \eqref{eqn:kkt-compl}, one can observe that there exists $\cA^0(\bp)\subseteq\cA'(\bp,\bq)\subseteq \cA^1(\bp)$ such that:
\begin{subequations}\label{eqn:compl-explicit}
\begin{align}
  \bA(\bp)[i,:]\bxi + \bB(\bp)[i,:]\bq &= 0,\; i\in \cA'(\bp,\bq)\\
  \bbeta[i] &= 0,\; i\in \cA^1(\bp)\setminus \cA'(\bp,\bq).
\end{align}
\end{subequations}
are satisfied at $\bxi^\dag(\bp,\bq)$, $\bbeta^\dag(\bp,\bq)$. Thus, from \eqref{eqn:kkt}, \eqref{eqn:compl-explicit}, and $\bbeta[i]=0$ for $i\in\mathbb{I}_{[1,\bm]}\setminus \cA^1(\bp)$ (from Lemma \ref{lem:nlp-sensitivity}), we have:

\begin{align}\label{eqn:linear-form-0}
  \begin{aligned}
  \begin{bmatrix}
    \bQ(\bp)& \bA(\bp)[\cA'(\bp,\bq),:]^\top\\
    \bA(\bp)[\cA'(\bp,\bq),:]
  \end{bmatrix}
  \begin{bmatrix}
    \bxi\\
    \bbeta[\cA'(\bp,\bq)]
  \end{bmatrix} &= -
  \begin{bmatrix}
    \bS(\bp)\\  
    \bB(\bp)[\cA'(\bp,\bq),:]
  \end{bmatrix}\bq\\
