  \cB'(\bp,\bq)&:=\phi(\mathbb{I}_{[1,\br]}\cup(\cA'(\bp,\bq)+\br)).
\end{align}
\end{subequations}

Finally, using the notation in \eqref{eqn:Bs}, we obtain the following from \eqref{eqn:linear-form-0}:
\begin{subequations}\label{eqn:linear-form}
\begin{align}
